  const cur = () => new Set(hc.map[key] || []), draw = () => { const H = cur(); pop.querySelector('[data-l]').innerHTML = names.map(n => `<label style="display:flex;gap:8px;padding:3px 2px;cursor:pointer"><input type="checkbox" data-n="${plEsc(n)}" ${H.has(n) ? '' : 'checked'} style="width:auto;margin:0"> <span>${plEsc(n)}</span></label>`).join(''); };
  pop.innerHTML = '<b>▦ Show / hide columns</b><div style="display:flex;gap:6px"><button type="button" class="ghost small" data-v="all">Show all</button><button type="button" class="ghost small" data-v="none">Hide all</button></div><div data-l style="overflow:auto;max-height:50vh"></div><span class="text-sm">Remembered in this browser for this table.</span>'; document.body.appendChild(pop); draw();
